const brpGeboortedatum = data.gegevensVanuitBronnen?.aanvrager?.geboortedatum;

const RE_YMD_DASHED = /^(\d{4})-(\d{2})-(\d{2})$/; // YYYY-MM-DD
const RE_YMD_PLAIN  = /^(\d{4})(\d{2})(\d{2})$/;   // YYYYMMDD

let output = '-';

if (typeof brpGeboortedatum === 'string') {
  const m = brpGeboortedatum.match(RE_YMD_DASHED) || brpGeboortedatum.match(RE_YMD_PLAIN);

  if (m) {
    const [, Y, M, D] = m;

    if (M === '00' || D === '00') {
      output = `${D}-${M}-${Y}`;
    } else {
      const mm = moment(`${Y}-${M}-${D}`, 'YYYY-MM-DD', true);
      output = mm.isValid() ? mm.format('DD-MM-YYYY') : `${D}-${M}-${Y}`;
    }
  } else {
    output = brpGeboortedatum;
  }
}

value = output;

